import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadDMSans = makeLoadFont('DMSans');

const { fontFamily: dmSansFamily } = loadDMSans();



export type DentalInsuranceProps = Record<string, any>;

const DentalInsurance: React.FC<DentalInsuranceProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  accentColor = "#00a8cc",
  textColor = "#1a1a1a",
  title = "What does dental insurance actually help with?",
  items = [
    "Preventive care (cleanings, exams, X-rays)",
    "Common procedures (fillings, extractions)",
    "Major treatments (crowns, root canals, orthodontia)",
  ],
  closingText = "Stay consistent with care to avoid bigger costs.",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Prevent parser errors by resolving transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const totalFrames = durationInSeconds * fps;
  const fadeOutStart = totalFrames - fps * 2.5; // Starts fading out 2.5s before the end
  const closingStart = totalFrames - fps * 2;   // Closing starts 2s before the end

  // OUTRO ANIMATIONS
  const mainOpacity = interpolate(
    frame,
    [fadeOutStart, fadeOutStart + 15],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const closingOpacity = interpolate(
    frame,
    [closingStart, closingStart + 20],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const closingY = spring({
    frame: frame - closingStart,
    fps,
    from: 40,
    to: 0,
    config: { damping: 14 },
  });

  const closingLineScale = spring({
    frame: frame - closingStart - 10,
    fps,
    from: 0,
    to: 1,
    config: { damping: 12 },
  });

  // INTRO ANIMATIONS - TOOTH
  const toothDraw = interpolate(frame, [0, 45], [100, 0], {
    extrapolateRight: "clamp",
  });
  
  const toothFillOpacity = interpolate(frame, [25, 45], [0, 1], {
    extrapolateRight: "clamp",
  });
  
  const toothScale = spring({
    frame,
    fps,
    from: 0.8,
    to: 1,
    config: { damping: 14 },
  });
  
  const floatY = Math.sin(frame / 15) * 8; // Gentle floating effect

  // INTRO ANIMATIONS - TITLE
  const titleY = spring({
    frame: frame - 15,
    fps,
    from: 30,
    to: 0,
    config: { damping: 14 },
  });
  const titleOpacity = interpolate(frame, [15, 30], [0, 1], {
    extrapolateRight: "clamp",
  });

  // HELPER: Renders the item text with bold main text and lighter parentheses
  const renderItemText = (text: string) => {
    const splitIndex = text.indexOf("(");
    if (splitIndex !== -1) {
      const main = text.substring(0, splitIndex).trim();
      const sub = text.substring(splitIndex).trim();
      return (
        <span style={{ transition: "none" }}>
          <span style={{ fontWeight: 700 }}>{main} </span>
          <span style={{ fontWeight: 400, opacity: 0.7 }}>{sub}</span>
        </span>
      );
    }
    return <span style={{ fontWeight: 700, transition: "none" }}>{text}</span>;
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: dmSansFamily,
        color: textColor,
        transition: "none",
      }}
    >
      {/* --- MAIN CONTENT SEQUENCE --- */}
      <AbsoluteFill
        style={{
          opacity: mainOpacity,
          justifyContent: "center",
          alignItems: "center",
          flexDirection: "row",
          padding: "0 5%",
          transition: "none",
        }}
      >
        <div
          style={{
            display: "flex",
            width: "100%",
            maxWidth: 1400,
            alignItems: "center",
            gap: 100,
            transition: "none",
          }}
        >
          {/* LEFT SIDE: Tooth & Title */}
          <div
            style={{
              flex: 1,
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-start",
              gap: 40,
              paddingRight: 40,
              transition: "none",
            }}
          >
            {/* Tooth SVG Container */}
            <div
              style={{
                transform: `scale(${toothScale}) translateY(${floatY}px)`,
                width: 220,
                height: 220,
                transition: "none",
              }}
            >
              <svg
                viewBox="0 0 24 24"
                style={{ width: "100%", height: "100%", overflow: "visible", transition: "none" }}
              >
                <path
                  d="M7 2.5C4 2.5 2 4.5 2 7.5C2 10.5 4 12 5 15C5.5 16.5 6 21 8 21C9.5 21 10.5 18.5 12 15C13.5 18.5 14.5 21 16 21C18 21 18.5 16.5 19 15C20 12 22 10.5 22 7.5C22 4.5 20 2.5 17 2.5C14 2.5 12 5 12 5C12 5 10 2.5 7 2.5Z"
                  fill={accentColor}
                  fillOpacity={toothFillOpacity}
                  stroke={accentColor}
                  strokeWidth={0.8}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  pathLength={100}
                  strokeDasharray={100}
                  strokeDashoffset={toothDraw}
                  style={{ transition: "none" }}
                />
              </svg>
            </div>
            
            {/* Title */}
            <h1
              style={{
                fontSize: 60,
                fontWeight: 700,
                lineHeight: 1.15,
                opacity: titleOpacity,
                transform: `translateY(${titleY}px)`,
                margin: 0,
                maxWidth: 600,
                letterSpacing: "-0.02em",
                transition: "none",
              }}
            >
              {title}
            </h1>
          </div>

          {/* RIGHT SIDE: List Items */}
          <div
            style={{
              flex: 1.2,
              display: "flex",
              flexDirection: "column",
              gap: 50,
              transition: "none",
            }}
          >
            {items.map((item, idx) => {
              const startFrame = 45 + idx * 20;
              const itemOpacity = interpolate(
                frame,
                [startFrame, startFrame + 15],
                [0, 1],
                { extrapolateRight: "clamp" }
              );
              const itemX = spring({
                frame: frame - startFrame,
                fps,
                from: 60,
                to: 0,
                config: { damping: 14, mass: 0.8 },
              });
              const bulletScale = spring({
                frame: frame - startFrame - 5,
                fps,
                from: 0,
                to: 1,
                config: { damping: 10 },
              });

              return (
                <div
                  key={idx}
                  style={{
                    display: "flex",
                    alignItems: "flex-start",
                    gap: 30,
                    opacity: itemOpacity,
                    transform: `translateX(${itemX}px)`,
                    transition: "none",
                  }}
                >
                  {/* Bullet */}
                  <div
                    style={{
                      width: 24,
                      height: 24,
                      borderRadius: "50%",
                      backgroundColor: accentColor,
                      flexShrink: 0,
                      marginTop: 16,
                      transform: `scale(${bulletScale})`,
                      transition: "none",
                    }}
                  />
                  {/* Text Container */}
                  <div
                    style={{
                      fontSize: 42,
                      lineHeight: 1.4,
                      letterSpacing: "-0.01em",
                      transition: "none",
                    }}
                  >
                    {renderItemText(item)}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>

      {/* --- CLOSING SCREEN --- */}
      <AbsoluteFill
        style={{
          opacity: closingOpacity,
          justifyContent: "center",
          alignItems: "center",
          padding: "0 10%",
          textAlign: "center",
          transition: "none",
          pointerEvents: "none",
        }}
      >
        <h2
          style={{
            fontSize: 72,
            fontWeight: 700,
            lineHeight: 1.2,
            transform: `translateY(${closingY}px)`,
            margin: 0,
            maxWidth: 1400,
            letterSpacing: "-0.02em",
            transition: "none",
          }}
        >
          {closingText}
        </h2>
        
        {/* Decorative Accent Line */}
        <div
          style={{
            width: 120,
            height: 8,
            backgroundColor: accentColor,
            borderRadius: 4,
            marginTop: 60,
            transform: `scaleX(${closingLineScale})`,
            transformOrigin: "center",
            transition: "none",
          }}
        />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default DentalInsurance;